INSERT INTO "website_config" ("key", "value", "updated_at") VALUES ('memberspage', '{"stats":[{"icon":"groups","label":" Hội viên","value":"61"},{"icon":"location_on","label":"Việt nam","value":"1"},{"icon":"verified","label":"Cam kết an toàn","value":"100%"},{"icon":"calendar_today","label":"Năm thành lập","value":"2025"}],"steps":[{"desc":"Doanh nghiệp điền thông tin và nộp hồ sơ đăng ký online.","icon":"description","step":"01","title":"Đăng ký hồ sơ"},{"desc":"Ban chấp hành xem xét, thẩm định và phê duyệt hồ sơ.","icon":"fact_check","step":"02","title":"Xét duyệt"},{"desc":"Kích hoạt quyền hội viên và bắt đầu các hoạt động kết nối.","icon":"handshake","step":"03","title":"Kết nối - Kích hoạt"},{"desc":"Hưởng đầy đủ quyền lợi và tham gia các sự kiện của Hiệp hội.","icon":"celebration","step":"04","title":"Tham gia cộng đồng"}],"subtext":"Nơi quy tụ các doanh nghiệp hàng đầu trong lĩnh vực Khí dầu mỏ hóa lỏng (LPG) tại Việt Nam, cam kết vì sự phát triển bền vững và an toàn năng lượng.","benefits":[{"desc":"Kết nối với cộng đồng hội viên và đối tác chiến lược trong ngành LPG toàn quốc.","icon":"hub","title":"Kết nối doanh nghiệp"},{"desc":"Cập nhật nhanh chóng chính sách, quy định pháp luật mới nhất liên quan đến khí hóa lỏng.","icon":"update","title":"Cập nhật chính sách"},{"desc":"Tham gia các buổi gặp mặt chia sẻ các kiến thức chuyên môn LPG","icon":"school","title":"Chia sẻ chuyên môn"},{"desc":"Cơ hội hợp tác, mở rộng thị trường và phát triển các liên kết kinh doanh bền vững.","icon":"rocket_launch","title":"Xúc tiến hợp tác"},{"desc":"Tư vấn, hỗ trợ pháp lý và bảo vệ quyền lợi hợp pháp của hội viên trong kinh doanh.","icon":"gavel","title":"Hỗ trợ pháp lý"},{"desc":"Tăng uy tín và hình ảnh thương hiệu thông qua các hoạt động cộng đồng của Hiệp hội.","icon":"verified","title":"Nâng cao uy tín"},{"desc":"Mô tả quyền lợi...","icon":"verified","title":"Quyền lợi mới"},{"desc":"Mô tả quyền lợi...","icon":"verified","title":"Quyền lợi mới"}],"headline":"Danh sách Hội viên Hiệp hội","sections":[{"id":"hero","name":"1. Banner chính","visible":true},{"id":"tabs","name":"2. Danh sách Hội viên","visible":true},{"id":"stats","name":"3. Thống kê tổng hợp","visible":true},{"id":"benefits","name":"4. Quyền lợi hội viên","visible":false},{"id":"steps","name":"5. Quy trình gia nhập","visible":true}],"heroImage":"https://lh3.googleusercontent.com/aida-public/AB6AXuBTP1VwRhiXz7IslKk8lyrl_NZjrM0MYtWMLyaBrXhEX2DRZ9wIHjlle-92NsUhnYmQwD4yTguPqimc2ewjOD30dygdkHwHt7s9NXsMPSnzWvTyHO_1lM5j2kM_9BcFoN9m67VEakH0ReGkHCz2mX7R0kfbHFSyqSNrqYFcUsBMK0sm4skbO_7LO2Qs237Mbc_zUrwOxQ0lEHdDE-3w74hK182bzXXoJ9Nz4No0EMfJPJZ14JUTiBDxNw-onJOCwry6C0bNPzf9aJY","associationRoles":[{"name":"Chủ tịch Hiệp Hội","color":"#bb0013","textColor":"#ffffff"},{"name":"Phó Chủ tịch Hiệp Hội","color":"#00346f","textColor":"#ffffff"},{"name":"Ban kiểm tra","color":"#d97706","textColor":"#ffffff"},{"name":"Ủy viên Ban Thường vụ","color":"#0284c7","textColor":"#ffffff"},{"name":"Ủy viên Ban Chấp hành","color":"#d7e2ff","textColor":"#001b3f"},{"name":"Hội viên chính thức","color":"#e7e5e4","textColor":"#1c1c1a"},{"name":"Hội viên liên kết","color":"#e7e5e4","textColor":"#1c1c1a"}]}', '"2026-06-05T08:42:30.056Z"') ON CONFLICT DO NOTHING;
INSERT INTO "website_config" ("key", "value", "updated_at") VALUES ('homepage', '{"stats":[{"icon":"groups","label":"Hội viên liên kết","value":"60+"},{"icon":"workspace_premium","label":"Năm hoạt động","value":"2+"},{"icon":"school","label":"Kết nối tạo giá trị","value":"100+"},{"icon":"handshake","label":"Đối tác chiến lược","value":"10+"}],"subtext":"Hiệp hội HOBA LPG hướng tới việc xây dựng môi trường kinh doanh an toàn, tuân thủ chặt chẽ các hành lang pháp lý đặc thù của Việt Nam trong lĩnh vực LPG","features":[{"id":"f1","desc":"Kiến nghị xây dựng các quy chuẩn kỹ thuật về an toàn LPG.","icon":"security","title":"Tiêu chuẩn an toàn"},{"id":"f2","desc":"Chia sẻ kiến thức quản trị trong ngành","icon":"school","title":"Chia sẻ kiến thức"},{"id":"1780283310992","desc":"Kết nối các doanh nghiệp trong và ngoài ngành","icon":"handshake","title":"Kết Nối"},{"id":"1780283346871","desc":"Thúc đẩy tính minh bạch của thị trường LPG.","icon":"groups","title":"Bảo vệ Cộng Đồng"}],"headline":"An toàn năng lượng - Phát triển bền vững","sections":[{"id":"hero","name":"1. Hero Banner","visible":true},{"id":"services","name":"3. Lĩnh vực hoạt động","visible":true},{"id":"news","name":"2. News & Events","visible":true},{"id":"stats","name":"4. Statistics Counter","visible":false},{"id":"members","name":"5. Hội viên tiêu biểu","visible":true}],"aboutDesc":"Hiệp hội Kinh doanh Khí hóa lỏng TP.HCM là tổ chức xã hội - nghề nghiệp tự nguyện của các doanh nghiệp, tổ chức và chuyên gia hoạt động trong lĩnh vực sản xuất, chiết nạp, lưu trữ, vận chuyển, kinh doanh và dịch vụ thương mại khí hóa lỏng (LPG) trên địa bàn Thành phố Hồ Chí Minh và các khu vực lân cận","heroImage":"/uploads/homepage/9dud1y1i5cs.jpeg","aboutImage":"/uploads/homepage/248l113laqaj.JPG","aboutTitle":"HIỆP HỘI KINH DOANH KHÍ HÓA LỎNG TP.HCM","heroBtn1Url":"/gioi-thieu","heroBtn2Url":"/dang-ky","coreServices":[{"desc":"Mở rộng mạng lưới hợp tác, chia sẻ nguồn lực và tạo dựng các mối quan hệ kinh doanh chiến lược.","icon":"handshake","title":"Kết nối doanh nghiệp","bgIcon":"diversity_3","showLink":false},{"desc":"Cung cấp báo cáo phân tích giá gas quốc tế, xu hướng tiêu dùng và biến động chính sách.","icon":"trending_up","title":"Phân tích thị trường","bgIcon":"query_stats","showLink":false},{"desc":"Tư vấn và phổ biến các thông tư, quy định mới liên quan đến kinh doanh và an toàn khí hóa lỏng.","icon":"gavel","title":"Tư vấn pháp lý","bgIcon":"balance","showLink":false},{"desc":"Chia sẻ kiến thức trong ngành LPG","icon":"engineering","title":"Chia sẻ an toàn","bgIcon":"school","showLink":false},{"desc":"Tổ chức các diễn đàn xúc tiến đầu tư và các buổi giao lưu ngành gas toàn quốc định kỳ.","icon":"groups_2","title":"Sự kiện & Hội Thảo","bgIcon":"event_seat","showLink":false},{"desc":"Tư vấn tháo gỡ vướng mắc về giấy phép và các thủ tục hành chính chuyên ngành năng lượng.","icon":"support_agent","title":"Hỗ trợ thủ tục","bgIcon":"health_and_safety","showLink":false}],"heroBtn1Show":true,"heroBtn1Text":"Khám phá","heroBtn2Show":true,"heroBtn2Text":"Đăng ký Hội viên","featuredMembers":[{"id":"sp1","logo":"https://lh3.googleusercontent.com/aida-public/AB6AXuCUSaADTHuO0LeW68laxKr1qy5yC1GTS_ZMkN3B3Bk8_GdXGeqGYbF0o9npgtS7B1SN9Q0rltt5aXIffVkM3BlPgVVzI8pArb-gKVO2tSlefjfbDUAlMaVWSsY4Eljq9-h-vBmck0v3SrFG9Mj-3v4ZjvKBtgZ4PzNjThhlqmt5XcMsoe9i24a1cqq-o4NItX0xwJ7eNBvZxigXmSDVsR6oQw5flyk3MYT4qmWEVd79cVskyyUgh0YrEvLEPsqb26TSmnVlXMPCh3I","name":"Saigon Petro"},{"id":"cg1","logo":"https://lh3.googleusercontent.com/aida-public/AB6AXuB-4CTXIocyVnnwyyHfAW2HBH3dLylJiYdJfzfRNk0sebpSDvYhL9ShY3uTaeX8Kca509b_k-2_UX7kcsoCDloaKRxN9FqWOSAIJ4zT4SUUrnCjxePkI5wOcmj63TodEipgcPO7KNuCorerGkEBENchfOaTXtDAFSwxE9sGyIGFf0GEK3QxcrGNWKxDi8WLTHLdj6X2NKVKo_i1y5GoL9X8w5iqqpca0J-qgEz159K6P6V7Wlw-gMDIqUJZ2ete1qlJtu3WQIUxMrU","name":"City Gas"},{"id":"vg1","logo":"https://lh3.googleusercontent.com/aida-public/AB6AXuC7eTnvK5aYgdRpQ7r0JrThIhssN0j12GcjAzcrszxjSAtC1JzdscsKEliCTSujgiOjdIduDejriCsmUzgC_jBK4p0R8HAqKoKN5vfBScoDvHnjlaz