INSERT INTO "website_config" ("key", "value", "updated_at") VALUES ('aboutpage', '{"values":[{"desc":"Đại diện và bảo vệ quyền, lợi ích hợp pháp của các hội viên; làm cầu nối vững chắc giữa doanh nghiệp với các cơ quan quản lý Nhà nước; thúc đẩy thị trường LPG phát triển minh bạch, lành mạnh, an toàn và bền vững.","icon":"ads_click","title":"Sứ mệnh"},{"desc":"Trở thành tổ chức hiệp hội ngành hàng uy tín, tiên phong trong việc chuẩn hóa an toàn phòng chống cháy nổ, và thúc đẩy chuyển đổi số, áp dụng công nghệ vào chuỗi cung ứng LPG tại Việt Nam.","icon":"visibility","title":"Tầm nhìn"},{"desc":"Đoàn kết - Vững tiến - Kiến tạo giá trị chung","icon":"diamond","title":"Giá trị cốt lõi"}],"heroDesc":"Hiệp hội Kinh doanh Khí hóa lỏng TP.HCM — Kết nối doanh nghiệp, đồng hành phát triển vì ngành LPG an toàn và bền vững.","overview":"Hiệp hội Kinh doanh Khí hóa lỏng TP.HCM là tổ chức xã hội - nghề nghiệp tự nguyện của các doanh nghiệp, tổ chức và chuyên gia hoạt động trong lĩnh vực sản xuất, chiết nạp, lưu trữ, vận chuyển, kinh doanh và dịch vụ thương mại khí hóa lỏng (LPG) trên địa bàn Thành phố Hồ Chí Minh và các khu vực lân cận","sections":[{"id":"hero","name":"1. Banner trang Giới thiệu","visible":true},{"id":"overview","name":"2. Tổng quan về HOBA","visible":true},{"id":"values","name":"3. Sứ mệnh - Tầm nhìn - Giá trị","visible":true},{"id":"timeline","name":"4. Lịch sử phát triển / Timeline","visible":true},{"id":"org","name":"5. Cơ cấu tổ chức","visible":true},{"id":"whyjoin","name":"6. Vì sao tham gia HOBA?","visible":true},{"id":"members","name":"7. Hội viên tiêu biểu","visible":true}],"heroImage":"/uploads/aboutpage/kdzi73862y.jpeg","heroTitle":"Giới thiệu HOBA","milestones":[{"id":"m1","date":"4/2025","desc":"Mốc thời gian thành lập đầu tiên.","title":"Hiệp hội Kinh doanh khí hóa lỏng (gas) tỉnh Bình Dương"},{"id":"m2","date":"11/2025","desc":"Mốc thời gian đổi tên chính thức.","title":"Đổi tên thành Hiệp hội kinh doanh khí hóa lỏng Tp HCM ( HOBA )"},{"id":"17803